        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "scope",
      "statement": "md_html is the entry's primary operation; its declared arguments include input bytes and size, an output callback and userdata, parser flags, and renderer flags.",
